    # piercings
    place = S("single lobe; double lobe; triple lobe; high lobe; helix; double helix; forward helix; tragus; anti-tragus; conch (inner and outer); daith; rook; industrial bar; snug; orbital; nostril; double nostril; septum; bridge; eyebrow; lip (labret); vertical labret; monroe; medusa; snake bites; ashley; tongue; cheek (dimple); navel; nipple; surface piercing on the collarbone; dermal anchor on the cheekbone; dermal anchor on the chest; stretched lobes")
    jew = S("a small gold stud; a silver hoop; a tiny gem stud; a captive bead ring; a curved barbell; a straight barbell with ball ends; a clicker hoop; a chain linking two piercings; a dangling charm; a feather earring; a spiral coil; a plug and tunnel; a clear retainer; a pearl stud; a colourful acrylic ring; a bone or horn earring; a heavy ear weight; a stacked row of tiny hoops; a titanium bar with a crystal end; a tusk-shaped taper")
