    art2 = S("intricate hand-drawn henna patterns on the hands and forearms; a full henna sleeve with floral motifs; bridal henna covering hands and feet; tribal-style geometric body paint; a painted-on tattoo-look design; glitter and gem body decoration; metallic gold leaf on the shoulders; UV neon body paint; traditional Polynesian-style patterns drawn on the skin; temporary transfer tattoos in a cluster; an abstract painted pattern across the torso; a painted floral crown on the bare skin; ritual painting in ochre and white clay on face and arms; tribal scarification patterns as raised lines; Maori-style moko facial patterns; Berber-style face tattoos; Dayak-style tattoos on the forearms; Samoan-style tattoo with geometric bands; Japanese-style full-sleeve tattoo; traditional flash tattoos in bright colours; old-school sailor tattoos; fine-line botanical tattoos; blackwork geometric tattoos; watercolour tattoos; portrait tattoos; script tattoos; chest piece; back piece; neck tattoo; hand tattoos; knuckle tattoos; face tattoos; tattoo-covered legs; stick-and-poke tattoos; UV-reactive tattoo; branded pattern as body art; ear tattoo; scalp tattoo; sleeves of mixed styles; cover-up tattoos")
    G['body_art'] = art2
