    frames = S("round wire-rimmed; square thick acetate; cat-eye; aviator; browline; oversized round; rectangular rimless; oval tortoiseshell; half-rim; hexagonal; butterfly; wayfarer; geometric angular; clubmaster-style; pince-nez; monocle on a chain; goggle-style steampunk; wraparound sport; shield visor; semi-rimless; transparent plastic; neon coloured; metal double bridge; librarian-style cat-eye with a chain; round John-Lennon-style; narrow rectangular fashion; oversized shield sunglasses; heart-shaped novelty; star-shaped novelty; mirrored sunglasses; round tinted sunglasses; ski goggles; swim goggles; welding goggles; safety glasses; 3D movie glasses; opera glasses on a stick; lorgnette with a handle; reading glasses perched low; half-moon reading glasses; clip-on flip-up; thick-lens magnifying; telescopic loupe glasses; tinted blue-light glasses; gradient lens fashion; cracked taped-up glasses; vintage cat-eye with rhinestones; 1920s round tortoiseshell; 1950s sharp cat-eye; 1970s oversized aviator; 1980s huge square; 1990s thin rectangular; 2000s tiny oval; 2020s thick bold")
    tint = S("clear lenses; light grey tint; dark black tint; amber tint; rose tint; blue tint; green tint; yellow tint; mirrored silver; mirrored blue; mirrored gold; gradient from dark to light; polarised brown; photochromic half-darkened")
    G['acc_eyewear'] = sorted({f"{f} glasses with {t}" for f in frames for t in tint if R('ew', f, t).random() < .30})
