    G['acc_eyewear_contact'] = S("natural-looking brown contacts; bright blue contacts; green cat-eye contacts; red demon contacts; solid black sclera lenses; white zombie contacts; yellow wolf-eye contacts; glowing UV contacts; mismatched coloured contacts; patterned spiral contacts; crazy mirror contacts; tiny pupil contacts; star-pupil novelty contacts")
